package com.mandu.liquiddialer
import androidx.compose.ui.test.*
import androidx.compose.ui.geometry.Offset
import com.mandu.liquiddialer.data.*
import com.mandu.liquiddialer.ui.*
import kotlinx.coroutines.runBlocking
import org.junit.*
import org.junit.Assert.*
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.*
@RunWith(RobolectricTestRunner::class) @Config(sdk=[34],qualifiers="w360dp-h800dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
class CanvasTransformUiTest:CallCanvasUiFixture(){
 private fun enable(){runBlocking{ctx.repo.set(K.canvasTransform,true)};await{LdApp.settings.value.canvasTransform}}
 private fun select(night:Boolean=false){show(night);enable();click("canvas_tool_select");scrollTo("canvas_paper");rule.onNodeWithTag("canvas_paper",true).performTouchInput{click(Offset(width*.18f,height*.5f))};settle();rule.onNodeWithTag("canvas_selection",true).assertTextContains("Selected stroke 1",substring=true)}
 @After fun resetTransform(){runBlocking{ctx.repo.set(K.canvasTransform,false)}}
 @Test fun defaultOffAndNoSelectedInkDisablesEdits(){show();assertFalse(LdApp.settings.value.canvasTransform);click("canvas_tool_select");rule.onAllNodesWithTag("canvas_transforms",true).assertCountEquals(0);enable();await{rule.onAllNodesWithTag("canvas_transform_smaller",true).fetchSemanticsNodes().isNotEmpty()};for(e in CanvasTransform.Edit.entries)rule.onNodeWithTag("canvas_transform_${e.name.lowercase()}",true).assertIsNotEnabled();assertEquals(sketch,CallCanvas.read(ctx,number).strokes)}
 @Test fun resizeIsUnsavedThenSingleUndoRedoAndSave(){select();click("canvas_transform_smaller");rule.onNodeWithTag("canvas_state",true).assertTextEquals("Unsaved drawing");assertEquals(sketch,CallCanvas.read(ctx,number).strokes);click("canvas_undo");rule.onNodeWithTag("canvas_state",true).assertTextEquals("Saved · 3 strokes");click("canvas_redo");click("canvas_save");await{CallCanvas.read(ctx,number).strokes!=sketch};val saved=CallCanvas.read(ctx,number).strokes;assertEquals(CanvasTransform.apply(sketch.first(),CanvasTransform.Edit.SMALLER,1.1),saved.first());assertEquals(sketch.drop(1),saved.drop(1))}
 @Test fun mirrorsTwiceReturnToOriginalWithoutFileWrites(){select();click("canvas_transform_mirror_x");click("canvas_transform_mirror_x");rule.onNodeWithTag("canvas_state",true).assertTextEquals("Saved · 3 strokes");click("canvas_transform_mirror_y");click("canvas_transform_mirror_y");rule.onNodeWithTag("canvas_state",true).assertTextEquals("Saved · 3 strokes");assertEquals(sketch,CallCanvas.read(ctx,number).strokes)}
 @Test fun rotationPreservesOtherStrokesAndStyle(){select();click("canvas_transform_right");assertEquals(sketch,CallCanvas.read(ctx,number).strokes);click("canvas_save");await{CallCanvas.read(ctx,number).strokes!=sketch};val n=CallCanvas.read(ctx,number).strokes;assertEquals(sketch.drop(1),n.drop(1));assertEquals(sketch.first().points.size,n.first().points.size);assertEquals(sketch.first().width,n.first().width);assertNotEquals(sketch.first(),n.first());assertTrue(CallCanvas.read(ctx,"+441234567890").strokes.isEmpty())}
 @Test fun edgeRejectionPreservesHistoryAndFile(){show(empty=true);val edge=CallCanvas.Stroke(0,2,listOf(CallCanvas.Point(0,0),CallCanvas.Point(10000,10000)));CallCanvas.save(ctx,number,"",listOf(edge));click("canvas_reload");await{rule.onAllNodesWithTag("canvas_state",true).fetchSemanticsNodes().any{it.config.getOrElse(androidx.compose.ui.semantics.SemanticsProperties.Text){emptyList()}.any{it.text=="Saved · 1 strokes"}}};enable();click("canvas_tool_select");scrollTo("canvas_paper");rule.onNodeWithTag("canvas_paper",true).performTouchInput{click(Offset(width*.5f,height*.5f))};settle();click("canvas_transform_bigger");rule.onNodeWithTag("canvas_transform_status",true).assertTextContains("Paper edge",substring=true);rule.onNodeWithTag("canvas_state",true).assertTextEquals("Saved · 1 strokes");assertEquals(listOf(edge),CallCanvas.read(ctx,number).strokes);click("canvas_undo");rule.onNodeWithTag("canvas_state",true).assertTextEquals("Unsaved drawing")}
 @Test fun settingOffHidesToolsAndKeepsUnsavedInk(){select();click("canvas_transform_smaller");runBlocking{ctx.repo.set(K.canvasTransform,false)};await{!LdApp.settings.value.canvasTransform&&rule.onAllNodesWithTag("canvas_transforms",true).fetchSemanticsNodes().isEmpty()};rule.onAllNodesWithTag("canvas_transforms",true).assertCountEquals(0);rule.onNodeWithTag("canvas_state",true).assertTextEquals("Unsaved drawing");click("canvas_save");await{CallCanvas.read(ctx,number).strokes!=sketch}}
 @Test fun transformedReopenAndNoCallOrIntent(){select();click("canvas_transform_left");click("canvas_save");await{CallCanvas.read(ctx,number).strokes!=sketch};val n=CallCanvas.read(ctx,number);rule.runOnUiThread{rule.activity.mountTestPage{LdThemeHost{CallCanvasWorkspace(number,{})}}};await{rule.onAllNodesWithTag("canvas_paper",true).fetchSemanticsNodes().isNotEmpty()};rule.onNodeWithTag("canvas_state",true).assertTextEquals("Saved · 3 strokes");assertEquals(n,CallCanvas.read(ctx,number));assertNull(org.robolectric.Shadows.shadowOf(rule.activity).nextStartedActivity)}
 @Test fun dayTransformedPixels(){select();click("canvas_transform_right");click("canvas_transform_smaller");scrollTo("canvas_paper");settle();saveShot(rule,"TRANSFORM426-day-paper");scrollTo("canvas_transforms");settle();saveShot(rule,"TRANSFORM426-day-tools")}
 @Test fun nightLargeTransformPixels(){select(true);click("canvas_transform_mirror_y");scrollTo("canvas_transforms");settle();saveShot(rule,"TRANSFORM426-night-large-tools");scrollTo("canvas_paper");settle();saveShot(rule,"TRANSFORM426-night-large-paper")}
 @Test fun settingsFinderAndControlPixels(){show();assertTrue(SettingsFinder.all.any{it.id=="canvas-transform"&&it.route=="callcanvas"});rule.runOnUiThread{rule.activity.mountTestPage{LdThemeHost{CallCanvasPage({})}}};settle();saveShot(rule,"TRANSFORM426-settings");assertFalse(LdApp.settings.value.canvasTransform)}
}
